import{_ as t,c as e,o as r,ah as o}from"./chunks/framework.l36K22_3.js";const p="/assets/2019011002090212.sVXA4dXi.png",s="/assets/2019011002090278.DGP3nyDz.png",l="/assets/2019011002090375.DRQkGLeO.png",g=JSON.parse('{"title":"金融行业的用户画像搭建与应用","description":"","frontmatter":{"title":"金融行业的用户画像搭建与应用"},"headers":[],"relativePath":"knowledge/study/user-portrait.md","filePath":"knowledge/study/user-portrait.md","lastUpdated":1788862678000}'),i={name:"knowledge/study/user-portrait.md"};function n(d,a,_,c,h,m){return r(),e("div",null,a[0]||(a[0]=[o('<h1 id="什么是用户画像" tabindex="-1">什么是用户画像 <a class="header-anchor" href="#什么是用户画像" aria-label="Permalink to &quot;什么是用户画像&quot;">​</a></h1><p>在移动营销时代里，得用户者得天下，而说到用户则不能不提用户画像。众所周知，商界流传着一句著名的话，那就是“我知道我的广告费有一半是浪费了，但我不知道是那一半被浪费了”。于是大家越来越强调精准投放，精准营销，然而在精准营销的领域里，这一切都离不开用户画像。</p><p>那什么是用户画像呢？用户画像就是对客户信息在特定业务场景下的系统描述，即用户信息标签化，通过收集用户社会属性、消费习惯、偏好特征等维度数据，并对这些特征属性进行刻画，分析和挖掘潜在价值信息，从而抽象出一个用户的信息全貌。</p><h1 id="如何构建用户画像" tabindex="-1">如何构建用户画像 <a class="header-anchor" href="#如何构建用户画像" aria-label="Permalink to &quot;如何构建用户画像&quot;">​</a></h1><ol><li>数据收集</li></ol><p>数据是构成用户画像的基础，没有数据的话，用户画像也无从说起，那如何进行用户数据收集呢？用户数据一般分为静态数据和动态数据。</p><p>一般来说，每个公司都会有自己的业务系统，可以收集到用户的基本属性信息和交易信息，例如用户的姓名、年龄、性别和投资产品、投资金额、交易时间等，这些一般是用户的静态数据。而用户的行为信息则是属于动态数据，这个一般是通过 SDK 埋点所获取的，例如用户注册、登录、页面浏览等事件信息。当然，还有第三方数据的采集购买，但这个是作为第一方数据的补充，在这里就不进行论述了。</p><ol start="2"><li>数据处理</li></ol><p>一般我们所获取到的数据都是原始数据来的，原始数据可能会存在着一些数据空缺、重复、或不一致等问题。因此我们还要对原数据进行清洗处理，才能从中抽取出有分析意义的数据，而数据清洗原则通常要结合具体业务场景进行制定。</p><ol start="3"><li>数据打通</li></ol><p>现在用户数据获取的来源有多个渠道，而要勾勒一个完整的用户视图，则离不开渠道间的数据打通，例如一个用户可能有多个设备，拥有多个账号，则要把多个身份 ID 进行组合，建立统一标准，才能构建完整的用户画像。</p><ol start="4"><li>用户数据标签化</li></ol><p>用户画像的本质，实际就是“标签化”的用户行为特征，通过给用户“打标签”如年龄、性别、兴趣爱好等，进行高度精炼的特征描述。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>而用户标签一般分为 3 类：</p><p>1）统计类标签：这类标签是最为基础也是最为常见的标签类型，主要是从原始数据中直接提取出来的，例如用户性别、年龄、城市等； 2）规则类标签：这类标签主要基于用户行为及确定规则所产生的，例如“活跃用户”而什么才算是活跃用户，这里标签的规则就主要是由运营人员或数据人员进行确定的； 3）挖掘类标签：这类标签主要是通过数据挖掘所产生，解决的是从无到有的问题，例如用户“性别”未知，但因中国人的名字和性别是强相关的，因此可以利用贝叶斯算法推测该用户性别。</p><p>用户标签体系的搭建是用户画像中最为核心的工作，因此在梳理标签体系时尽量按照 MECE 原则，做到相互独立，完全穷尽。例如下图中互金行业的标签体系搭建。</p><p><img src="'+s+'" alt="" loading="lazy"></p><h1 id="用户画像的实际运用" tabindex="-1">用户画像的实际运用 <a class="header-anchor" href="#用户画像的实际运用" aria-label="Permalink to &quot;用户画像的实际运用&quot;">​</a></h1><p>不同的企业做用户画像会有不同的战略目的，例如广告平台，主要是为了精准投放，找到目标用户，而内容平台是为了个性化推荐，更好的留住用户，数据类平台，则是进行用户分析，挖掘数据价值，驱动运营增长；</p><p>而对于金融行业来说，金融服务目前正在由以产品为中心转向以用户为中心。面对不同的用户类型，用户群体的细分就显得非常重要，例如有些客户是稳健型投资者，偏好保本收益，有些则是激进型投资者，偏好高风险收益，那这时就应该要为不同用户群体设计不同的金融产品。同样，针对不同年龄段、不同职业、不同偏好的用户，所采取的营销策略也会不一样。这时就可以根据用户属性信息、消费特征、兴趣偏好等来为不同的用户提供不同的产品服务与营销策略。</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>在精准营销的领域当中，用户画像是必不可缺的，一个好的用户画像可以帮助企业进行产品定位，人群细分，指导营销决策。但用户画像的搭建与使用必须结合具体的业务场景，否则就算是有再多的数据维度，再完整的用户画像，也无法发挥作用。 <br><br><br></p>',23)]))}const f=t(i,[["render",n]]);export{g as __pageData,f as default};
